def checkInclusion(s1, s2):
    if len(s1) > len(s2):
        return False
    c1 = Counter(s1)
    window = Counter(s2[:len(s1)])
    if c1 == window:
        return True
    for i in range(len(s1), len(s2)):
        window[s2[i]] += 1
        window[s2[i - len(s1)]] -= 1
        if window[s2[i - len(s1)]] == 0:
            del window[s2[i - len(s1)]]
        if window == c1:
            return True
    return False
